CREATE TABLE IF NOT EXISTS place_views(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,place_id BIGINT UNSIGNED NOT NULL,visitor_id CHAR(36) NOT NULL,event_type ENUM('view','click','favorite') NOT NULL DEFAULT 'view',device ENUM('mobile','desktop','tablet') NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_place_views_place_date(place_id,created_at),KEY idx_place_views_event_date(event_type,created_at),CONSTRAINT fk_place_views_place FOREIGN KEY(place_id) REFERENCES places(id) ON DELETE CASCADE ON UPDATE CASCADE);